js:function(context, args) {
  var actor = args && args.actor;
  if (actor === undefined || actor === null || actor === '') {
    return {defer: 'missing current arguments', parameters: 'describe ONLY missing ordinary args fields: actor'};
  }
  var hist = context.history || [];
  var lastSubmitId = null;
  var done = null;
  var statusOcc = 0;
  for (var i = 0; i < hist.length; i++) {
    var h = hist[i] || {};
    var c = (h.arguments && h.arguments.command) || '';
    if (c.indexOf('experiment submit') === 0 || c.indexOf('experiment append') === 0) {
      var t = h.text || '';
      var m = t.match(/native_operation_id"?:\s*"([^"]+)"/);
      if (m) lastSubmitId = m[1];
      else if (h.data && h.data.native_operation_id) lastSubmitId = h.data.native_operation_id;
      else lastSubmitId = h.call_id;
    }
    if (c.indexOf('experiment status') === 0) {
      statusOcc++;
      if (h.data && h.data.complete === true) {
        done = {receipt: h.data.receipt, native_operation_id: h.data.native_operation_id || lastSubmitId};
      }
    }
  }
  if (done) return {report: done};
  if (!lastSubmitId) {
    var r1 = execute({name: 'bash', arguments: {command: command('experiment', ['submit', actor])}, read: false, step: 'submit', occurrence: 0});
    var t1 = (r1 && r1.text) || '';
    var m1 = t1.match(/native_operation_id"?:\s*"([^"]+)"/);
    if (m1) lastSubmitId = m1[1];
    else if (r1 && r1.data && r1.data.native_operation_id) lastSubmitId = r1.data.native_operation_id;
    else if (r1 && r1.call_id) lastSubmitId = r1.call_id;
    if (!lastSubmitId) return {defer: 'experiment submit gave no native operation id' };
    statusOcc = 0;
  }
  var st = execute({name: 'bash', arguments: {command: command('experiment', ['status', lastSubmitId])}, read: true, step: 'poll', occurrence: statusOcc});
  if (!st) return {defer: 'no response from experiment status' };
  if (st.is_error) return {defer: 'experiment status errored' };
  var d = st.data || {};
  if (d.complete === true) return {report: {receipt: d.receipt, native_operation_id: d.native_operation_id || lastSubmitId}};
  return {defer: 'experiment ' + lastSubmitId + ' not complete yet; re-invoke to poll' };
}

