js:function(context, args) {
  var term = args && args.term;
  var session = (args && args.session) || 's1';
  if (!term) return {defer: 'missing current arguments', parameters: 'term (exact search string); optional session, url'};

  var history = context.history || [];
  function occOf(sub) {
    var occ = 0;
    for (var i = 0; i < history.length; i++) {
      var h = history[i];
      if (h.name === 'bash' && h.arguments && typeof h.arguments.command === 'string' && h.arguments.command.indexOf(sub) !== -1) occ++;
    }
    return occ;
  }

  var snap = execute({name: 'bash', arguments: {command: command('playwright', ['snapshot', session, '--json'])}, read: true});
  var pageData = (snap && snap.data) || null;
  if (!pageData && snap && snap.text) { try { pageData = JSON.parse(snap.text); } catch (e) { pageData = null; } }
  if (!pageData || !pageData.elements) return {defer: 'snapshot unavailable for session ' + session};

  var input = null, button = null, i;
  for (i = 0; i < pageData.elements.length; i++) {
    var el = pageData.elements[i];
    if (!input && el.tag === 'input' && el.visible && !el.disabled) input = el;
    if (!button && el.tag === 'button' && el.visible && !el.disabled && /find|search|submit|go/i.test(el.text || '')) button = el;
  }
  if (!button) for (i = 0; i < pageData.elements.length; i++) { var b = pageData.elements[i]; if (b.tag === 'button' && b.visible && !b.disabled) { button = b; break; } }
  if (!input) return {defer: 'no visible search input found on current page'};
  if (!button) return {defer: 'no visible submit button found on current page'};

  execute({name: 'bash', arguments: {command: command('playwright', ['fill', session, input.address, term])}, read: false, step: 'fill', occurrence: occOf('playwright fill')});
  execute({name: 'bash', arguments: {command: command('playwright', ['click', session, button.address])}, read: false, step: 'click', occurrence: occOf('playwright click')});

  var out = null;
  for (var n = 0; n < 5; n++) {
    var s2 = execute({name: 'bash', arguments: {command: command('playwright', ['snapshot', session, '--json'])}, read: true});
    var d2 = (s2 && s2.data) || null;
    if (!d2 && s2 && s2.text) { try { d2 = JSON.parse(s2.text); } catch (e) { d2 = null; } }
    if (d2 && d2.elements) {
      for (i = 0; i < d2.elements.length; i++) { if (/receipt/i.test(d2.elements[i].text || '')) { out = d2.elements[i].text; break; } }
      if (out) break;
    }
  }
  if (!out) return {defer: 'no receipt observed after submitting query'};
  return {report: {receipt: out, term: term}};
}

